create extension if not exists pg_trgm;
create extension if not exists pgcrypto;
create table public.recipes (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),status text not null default 'published' check(status in ('published','hidden')),slug text not null unique,title text not null,description text,servings numeric,prep_minutes integer,cook_minutes integer,ingredients jsonb not null default '[]'::jsonb,instructions jsonb not null default '[]'::jsonb,nutrition jsonb not null default '{}'::jsonb,calories numeric generated always as ((nutrition->>'calories')::numeric) stored,protein numeric generated always as ((nutrition->>'protein')::numeric) stored,carbs numeric generated always as ((nutrition->>'carbs')::numeric) stored,fat numeric generated always as ((nutrition->>'fat')::numeric) stored,cuisine text,meal_type text,tags text[] not null default '{}',source_platform text,source_url text unique,contributor_name text,source_image_url text);
create index recipes_published_created_idx on public.recipes(status,created_at desc);create index recipes_title_trgm_idx on public.recipes using gin(title gin_trgm_ops);create index recipes_tags_idx on public.recipes using gin(tags);create index recipes_filter_idx on public.recipes(status,cuisine,protein,calories);alter table public.recipes enable row level security;create policy "Public reads published recipes" on public.recipes for select using (status='published');
-- Writes intentionally go only through the server route using the service key, where rate limiting and duplicate detection run.
insert into storage.buckets (id,name,public) values ('recipe-images','recipe-images',true) on conflict do nothing;
